    view-timeline-name: --card-reveal;
    view-timeline-axis: block;
    animation-name: matrix-scan-reveal;
    animation-fill-mode: both;
    animation-timeline: --card-reveal;
    animation-range: entry 0% cover 30%;
}

@starting-style {
